package br.com.admeclesial.domain.organizacao;
import br.com.admeclesial.domain.pessoa.Pessoa; import jakarta.persistence.*; import java.time.LocalDate; import java.util.UUID;
@Entity @Table(name="vinculo_pessoa_organizacao_eclesial",schema="adm_eclesial") public class VinculoPessoaOrganizacaoEclesial {
 @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(nullable=false,unique=true,updatable=false) private UUID uuid; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="pessoa_id",nullable=false) private Pessoa pessoa; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="organizacao_eclesial_id",nullable=false) private OrganizacaoEclesial organizacaoEclesial; @Column(name="data_inicio",nullable=false) private LocalDate dataInicio; @Column(name="data_fim") private LocalDate dataFim; @Enumerated(EnumType.STRING) @Column(nullable=false,length=20) private StatusVinculoPessoaOrganizacao status=StatusVinculoPessoaOrganizacao.ATIVO; @Column(nullable=false) private boolean principal; @Column(columnDefinition="text") private String observacao;
 @PrePersist void prePersist(){if(uuid==null)uuid=UUID.randomUUID();}
 public Long getId(){return id;} public UUID getUuid(){return uuid;} public void setPessoa(Pessoa v){pessoa=v;} public void setOrganizacaoEclesial(OrganizacaoEclesial v){organizacaoEclesial=v;} public void setDataInicio(LocalDate v){dataInicio=v;} public void setDataFim(LocalDate v){dataFim=v;} public void setStatus(StatusVinculoPessoaOrganizacao v){status=v;} public void setPrincipal(boolean v){principal=v;} public void setObservacao(String v){observacao=v;} public Pessoa getPessoa(){return pessoa;} public OrganizacaoEclesial getOrganizacaoEclesial(){return organizacaoEclesial;} public LocalDate getDataInicio(){return dataInicio;} public LocalDate getDataFim(){return dataFim;} public StatusVinculoPessoaOrganizacao getStatus(){return status;} public boolean isPrincipal(){return principal;} public String getObservacao(){return observacao;}
}
